import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';

/**
 * An accordion with multiple collapsible panels allowing one or multiple active keys.
 * Requires: useState, activeKeys, toggle
 */
export function Accordion({ panels = [], allowMultiple = false }) {

ground_truth_solution:
    const [active, setActive] = useState(new Set());
    const toggle = (id) => {
        setActive(prev => {
            const next = allowMultiple ? new Set(prev) : new Set();
            if (prev.has(id)) next.delete(id); else next.add(id);
            return next;
        });
    };
    return (
        <div className="accordion">
            {panels.map(p => (
                <div key={p.id} className="panel">
                    <button onClick={() => toggle(p.id)}>{p.title}</button>
                    {active.has(p.id) && <div className="content">{p.content}</div>}
                </div>
            ))}
        </div>
    );
}

