        <div className="stopwatch">
            <h2>{seconds}s</h2>
            <button onClick={() => setRunning(r => !r)}>{running ? 'Pause' : 'Start'}</button>
            <button onClick={() => { setRunning(false); setSeconds(0); }}>Reset</button>
        </div>
    );
}

