import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';

/**
 * Todo item manager with add, toggle complete, and delete actions.
 * Requires: useState, todos, toggleTodo, deleteTodo
 */
export function TodoList({ initialTodos = [] }) {

ground_truth_solution:
    const [todos, setTodos] = useState(initialTodos);
    const [text, setText] = useState('');
    const addTodo = (e) => {
        e.preventDefault();
        if (!text.trim()) return;
        setTodos(prev => [...prev, { id: Date.now(), text: text.trim(), completed: false }]);
        setText('');
    };
    const toggle = (id) => setTodos(prev => prev.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
    const remove = (id) => setTodos(prev => prev.filter(t => t.id !== id));
    return (
        <div className="todo-list">
            <form onSubmit={addTodo}>
                <input value={text} onChange={e => setText(e.target.value)} placeholder="New todo..." />
                <button type="submit">Add</button>
            </form>
            <ul>
                {todos.map(t => (
                    <li key={t.id} style={{ textDecoration: t.completed ? 'line-through' : 'none' }}>
                        <span onClick={() => toggle(t.id)}>{t.text}</span>
                        <button onClick={() => remove(t.id)}>Delete</button>
                    </li>
                ))}
            </ul>
        </div>
    );
}

